//! The Minecraft map: a world generated by MinecraftOSS, played on top of a
//! small IW4 map loaded only for the shared weapon, body and menu content.
//! None of that map's world is shown or collided with.
use asset_transport::{GamesRoot, ZoneFile};

pub const ZONE: &str = "minecraft:overworld";
const PROXY_ZONE: &str = "iw4:mp_rust";
/// The map whose level script the Minecraft world runs.
pub const PROXY_MAP: &str = "mp_rust";

pub fn is_minecraft(zone: &str) -> bool {
    zone.eq_ignore_ascii_case(ZONE)
}

/// Whether a load's zone, with or without its content namespace, is the
/// Minecraft map.
pub fn is_minecraft_load(zone: &str) -> bool {
    is_minecraft(zone) || zone.split_once(':').is_some_and(|(_, rest)| is_minecraft(rest))
}

pub fn disarm_proxy_entities(entities: &mut [Vec<(String, String)>]) -> usize {
    let mut disarmed = 0;
    for entity in entities.iter_mut().filter(|pairs| kills_players(pairs)) {
        entity.clear();
        disarmed += 1;
    }
    disarmed
}

fn kills_players(pairs: &[(String, String)]) -> bool {
    pairs.iter().any(|(key, value)| {
        key.eq_ignore_ascii_case("classname") && value.eq_ignore_ascii_case("trigger_hurt")
    })
}

pub fn disarm_proxy_script(scripts: &mut crate::ScriptSources) -> bool {
    let module = format!("maps/mp/{PROXY_MAP}");
    let Ok(bytes) = scripts.read(&module) else {
        return false;
    };
    let source = String::from_utf8(bytes)
        .unwrap_or_else(|error| error.into_bytes().into_iter().map(char::from).collect());
    let mut disarmed = false;
    let kept: String = source
        .split_inclusive('\n')
        .map(|line| {
            if calls_kill_trigger(line) {
                disarmed = true;
                &line[line.trim_end_matches(['\r', '\n']).len()..]
            } else {
                line
            }
        })
        .collect();
    if disarmed {
        scripts.insert_source(&module, kept);
    }
    disarmed
}

fn calls_kill_trigger(line: &str) -> bool {
    let code = line
        .chars()
        .filter(|c| !c.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    let call = code.strip_prefix("thread").unwrap_or(&code);
    call.starts_with("killtrigger(") && call.ends_with(");")
}

/// Where the world's Minecraft files are: a MinecraftOSS checkout named by
/// `MINECRAFTOSS_ROOT`, else the files fetched from Mojang once they are in.
pub fn root() -> Option<std::path::PathBuf> {
    if let Some(root) = std::env::var_os("MINECRAFTOSS_ROOT").map(std::path::PathBuf::from)
        && root.join("datapacks").is_dir()
    {
        return Some(root);
    }
    crate::minecraft_setup::ready()
}

/// Starts fetching Minecraft's files from Mojang when nothing supplies them.
pub fn prepare() {
    match root() {
        Some(root) => crate::minecraft_setup::begin_end_music(&root),
        None => crate::minecraft_setup::begin(),
    }
}

pub fn find_zone_file(root_dir: &GamesRoot, zone: &str) -> Result<ZoneFile, String> {
    if !is_minecraft_load(zone) {
        return asset_transport::find_zone_file(root_dir, zone);
    }
    let checkout = match root() {
        Some(root) => root,
        None => {
            // A first run straight into this map waits for Mojang's files.
            crate::minecraft_setup::begin();
            diag::info!(World, "Minecraft map: waiting for Minecraft's files from Mojang");
            // Briefly: a load held much longer does not come back cleanly,
            // and the fetch carries on for the next try.
            crate::minecraft_setup::wait(std::time::Duration::from_secs(90))
                .ok_or_else(crate::minecraft_setup::status)?
        }
    };
    let mut proxy = asset_transport::find_zone_file(root_dir, PROXY_ZONE)?;
    proxy.zone_name = ZONE.to_owned();
    proxy.alias_note = Some(format!("Minecraft world from {}", checkout.display()));
    Ok(proxy)
}

/// The installed map packs, with the Minecraft world as a pack of its own
/// when the map it stands in for is installed.
pub fn list_mp_map_packs(root_dir: &GamesRoot) -> Vec<asset_transport::MapPack> {
    prepare();
    let mut packs = asset_transport::list_mp_map_packs(root_dir);
    if asset_transport::find_zone_file(root_dir, PROXY_ZONE).is_ok() {
        packs.push(asset_transport::MapPack {
            label: "Minecraft".to_owned(),
            maps: vec![ZONE.to_owned()],
        });
    }
    packs
}

pub fn list_mp_maps(root_dir: &GamesRoot) -> Vec<String> {
    let mut maps = asset_transport::list_mp_maps(root_dir);
    // Listed before Mojang's files are in: loading it waits for them.
    prepare();
    if asset_transport::find_zone_file(root_dir, PROXY_ZONE).is_ok() {
        maps.push(ZONE.to_owned());
    }
    maps.sort();
    maps.dedup();
    maps
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entity(pairs: &[(&str, &str)]) -> Vec<(String, String)> {
        pairs
            .iter()
            .map(|(key, value)| ((*key).to_owned(), (*value).to_owned()))
            .collect()
    }

    fn source(scripts: &crate::ScriptSources, module: &str) -> String {
        String::from_utf8(scripts.read(module).unwrap()).unwrap()
    }

    #[test]
    fn proxy_trigger_hurts_are_emptied_in_place_and_other_entities_kept() {
        let mut entities = vec![
            entity(&[("classname", "worldspawn")]),
            entity(&[
                ("dmg", "10000"),
                ("classname", "trigger_hurt"),
                ("origin", "304 704 -1952"),
                ("model", "?15"),
            ]),
            entity(&[("classname", "script_model"), ("model", "foliage_tree")]),
            entity(&[
                ("classname", "trigger_radius"),
                ("targetname", "flag_primary"),
            ]),
            entity(&[("CLASSNAME", "Trigger_Hurt")]),
            entity(&[("classname", "mp_dm_spawn"), ("origin", "0 0 0")]),
        ];
        let before = entities.clone();
        assert_eq!(disarm_proxy_entities(&mut entities), 2);
        assert_eq!(entities.len(), before.len());
        assert!(entities[1].is_empty());
        assert!(entities[4].is_empty());
        for index in [0, 2, 3, 5] {
            assert_eq!(entities[index], before[index]);
        }
        assert_eq!(disarm_proxy_entities(&mut entities), 0);
    }

    #[test]
    fn the_proxy_map_script_loses_its_kill_trigger_and_keeps_the_rest() {
        let main = [
            "main()",
            "{",
            "\tmaps\\mp\\_load::main();",
            "",
            "\tgame[ \"attackers\" ] = \"allies\";",
            "\tthread killTrigger( (1080, 1645, -156 - 30), 40, 30 );",
            "}",
        ];
        let utility = [
            "killTrigger( pos, radius, height )",
            "{",
            "\ttrig = spawn( \"trigger_radius\", pos, 0, radius, height );",
            "}",
            "",
        ]
        .join("\n");
        let mut scripts = crate::ScriptSources::default();
        scripts.insert_source("maps/mp/mp_rust", main.join("\n"));
        scripts.insert_source("maps/mp/_utility", utility.clone());
        assert!(disarm_proxy_script(&mut scripts));
        let mut kept = main;
        kept[5] = "";
        assert_eq!(source(&scripts, "maps/mp/mp_rust"), kept.join("\n"));
        assert_eq!(source(&scripts, "maps/mp/_utility"), utility);
        assert!(!disarm_proxy_script(&mut scripts));
    }

    #[test]
    fn a_kill_trigger_call_goes_whatever_its_spacing_and_line_endings() {
        let main = [
            "main()",
            "{",
            "\tambientPlay( \"ambient_mp_duststorm\" );",
            "\tthread\tKillTrigger((1, 2, 3), 40, 30);",
            "  killtrigger ( (4, 5, 6), 8, 9 ) ;",
            "}",
            "",
        ];
        let mut scripts = crate::ScriptSources::default();
        scripts.insert_source("maps/mp/mp_rust", main.join("\r\n"));
        assert!(disarm_proxy_script(&mut scripts));
        let mut kept = main;
        kept[3] = "";
        kept[4] = "";
        assert_eq!(source(&scripts, "maps/mp/mp_rust"), kept.join("\r\n"));
    }

    #[test]
    fn scripts_without_the_proxy_map_or_its_kill_trigger_are_left_alone() {
        let mut scripts = crate::ScriptSources::default();
        assert!(!disarm_proxy_script(&mut scripts));
        let main = [
            "main()",
            "{",
            "\tlevel thread killTriggers();",
            "\tkillTriggerDebug( pos );",
            "\tthread killTrigger( pos, 40,",
            "\t\t30 );",
            "}",
        ]
        .join("\n");
        scripts.insert_source("maps/mp/mp_rust", main.clone());
        assert!(!disarm_proxy_script(&mut scripts));
        assert_eq!(source(&scripts, "maps/mp/mp_rust"), main);
    }
}
